            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "La poetica è per entrambi quella di «semplificare le umane passioni»; ma quella di Verga prende avvio da un ritorno, quella di Guttuso da una fuga. La differenza non è trascurabile.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "La sicurezza del potere si fonda sull'insicurezza dei cittadini.", Author = "Leonardo Sciascia" },
