            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "Non c'è nulla di più falso che il proclama di Mussolini secondo cui la Sicilia era fascista fino al midollo.", Author = "Leonardo Sciascia" },
