            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "Poiché nulla di sé e del mondo sa la generalità degli uomini, se la letteratura non glielo apprende.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "E sa che penso? Che la Chiesa cattolica stia registrando oggi il suo più grande trionfo: l'uomo odia finalmente la donna.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "«Sai come si dice? Tre c sono pericolose: cugini, cognati e compari. Le tresche più gravi si verificano quasi sempre nella parentela e nel comparatico».", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "''L'espresso'', 20 febbraio 1983 [...] Non credendo, dunque, di far parte di una categoria, corporazione o sindacato, se qualcuno mi corre dietro chiamandomi \"intellettuale\" non mi volto nemmeno.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "Noi siamo quel che facciamo. Le intenzioni, specialmente se buone, e i rimorsi, specialmente se giusti, ognuno, dentro di sé, può giocarseli come vuole, fino alla disintegrazione, alla follia.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "Tante cose si fanno per il bene degli altri che diventano il male degli altri e il proprio.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "Ché a vederle, le cose si semplificano: e noi abbiamo invece bisogno di complicarle, di farne complicate analisi, di trovarne complicate cause, ragioni, giustificazioni.", Author = "Leonardo Sciascia" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_Sciascia", Text = "Sai cos'è la nostra vita? La tua e la mia? Un sogno fatto in Sicilia. Forse stiamo ancora lì e stiamo sognando.", Author = "Leonardo Sciascia" },
